var a={concepto:"La f\xF3rmula de Cardano resuelve la c\xFAbica a\xB7x\xB3 + b\xB7x\xB2 + c\xB7x + d = 0 en forma cerrada. Primero se reduce a la forma deprimida x\xB3 + p\xB7x + q = 0 con el cambio x = t \u2212 b/(3a), luego se calcula el discriminante \u0394 = (q/2)\xB2 + (p/3)\xB3 y, seg\xFAn su signo, se obtienen las ra\xEDces reales (y complejas) mediante radicales o mediante la trigonometr\xEDa de Vi\xE8te cuando \u0394 < 0 (tres ra\xEDces reales).",fundamento:"La idea es eliminar el t\xE9rmino cuadr\xE1tico: el desplazamiento m = \u2212b/(3a) centra la c\xFAbica. En la variable t = x \u2212 m queda t\xB3 + p\xB7t + q = 0 con p,q en funci\xF3n de a,b,c,d. Cardano propuso t = u+v con (u+v)\xB3 = u\xB3+v\xB3 + 3uv(u+v)=u\xB3+v\xB3 + 3uv\xB7t, lo que lleva a 3uv = \u2212p, u\xB3+v\xB3 = \u2212q, y por tanto u\xB3,v\xB3 son ra\xEDces de y\xB2 \u2212 (u\xB3+v\xB3)y + (uv)\xB3 = 0. As\xED se obtienen u\xB3,v\xB3 por f\xF3rmula cuadr\xE1tica y luego t = \xB3\u221Au\xB3 + \xB3\u221Av\xB3 (con las ra\xEDces c\xFAbicas adecuadas). Si \u0394 < 0, las ra\xEDces c\xFAbicas son complejas conjugadas y conviene usar la forma trigonom\xE9trica de Vi\xE8te para obtener las tres ra\xEDces reales directamente.",cuandoFalla:"Cardano requiere que el polinomio sea de grado 3 (a != 0). Si es de grado < 3 o > 3, no corresponde aplicar esta f\xF3rmula. Tampoco resuelve funciones trascendentes (e\u02E3, sen(x), ln(x)). Cuando hay ra\xEDces m\xFAltiples (\u0394=0) las f\xF3rmulas siguen valiendo con cuidado num\xE9rico (umbral |\u0394| \u2264 1e-12\xB7max(1,|p|,|q|)). Adem\xE1s, la forma algebraica cl\xE1sica puede presentar casus irreducibilis (\u0394<0) que se maneja con Vi\xE8te trigonom\xE9trico para obtener ra\xEDces reales sin pasar por complejos expl\xEDcitos en esta implementaci\xF3n did\xE1ctica.",ordenConvergencia:"Es una resoluci\xF3n cerrada: no hay iteraciones, las ra\xEDces se calculan directamente mediante f\xF3rmulas algebraicas (o trigonom\xE9tricas). Por eso decimos \xAB0 iteraciones\xBB y el resultado se obtiene en un \xFAnico desarrollo paso a paso.",videoUrl:void 0,algoritmo:{formula:"x = t \u2212 b/(3a), t\xB3 + p\xB7t + q = 0, p = (3a c \u2212 b\xB2)/(3a\xB2), q = (2b\xB3 \u2212 9a b c + 27a\xB2 d)/(27a\xB3). \u0394 = (q/2)\xB2 + (p/3)\xB3. Si \u0394 > 0: t_k = \u03C9^k \xB7 A^(1/3) + \u03C9^(2k) \xB7 B^(1/3), A = \u2212q/2 + \u221A\u0394, B = \u2212q/2 \u2212 \u221A\u0394, \u03C9 primitiva c\xFAbica. Si \u0394 == 0: t\u2081 = \u22122\xB7(q/2)^(1/3), t\u2082 = t\u2083 = (q/2)^(1/3). Si \u0394 < 0: t_k = 2\xB7\u221A(\u2212p/3)\xB7cos((\u03C6 \u2212 2k\u03C0)/3), \u03C6 = arccos((\u2212q/2)/\u221A(\u2212(p/3)\xB3)), k=0,1,2.",criterios:[{nombre:"Grado del polinomio",explicacion:"Debe ser a\xB7x\xB3 + b\xB7x\xB2 + c\xB7x + d = 0 con a != 0. Si grado != 3, el m\xE9todo no aplica."},{nombre:"Discriminante \u0394",explicacion:"\u0394 = (q/2)\xB2 + (p/3)\xB3 decide el caso: \u0394 > 0 \u2192 una ra\xEDz real + dos complejas conjugadas (mostramos la real principal); \u0394 == 0 \u2192 ra\xEDz m\xFAltiple (al menos doble); \u0394 < 0 \u2192 tres ra\xEDces reales distintas (Vi\xE8te trigonom\xE9trico)."},{nombre:"Umbral num\xE9rico",explicacion:"Para evitar falsos positivos/negativos por redondeo, usamos |\u0394| \u2264 \u03B5\xB7M con \u03B5=1e-12 y M = max(1, |p|, |q|) para tratar \u0394\u22480 como cero."}],pasos:["Extraer coeficientes a,b,c,d de la funci\xF3n f(x)=a x\xB3 + b x\xB2 + c x + d.","Calcular m = \u2212b/(3a) (desplazamiento) para reducir a forma deprimida.","Calcular p = (3a c \u2212 b\xB2)/(3a\xB2), q = (2b\xB3 \u2212 9a b c + 27a\xB2 d)/(27a\xB3). Obtener t\xB3 + p t + q = 0.","Calcular \u0394 = (q/2)\xB2 + (p/3)\xB3. Aplicar umbral si corresponde.","Seg\xFAn \u0394: si > 0 obtener t con Cardano cl\xE1sico (una real); si == 0 obtener ra\xEDces m\xFAltiples; si < 0 obtener tres t con Vi\xE8te trigonom\xE9trico.","Deshacer desplazamiento: x = t + m para cada ra\xEDz real encontrada.","Verificar orden y presentar ra\xEDces reales (de menor a mayor)."],ventajas:["Resoluci\xF3n cerrada: no itera, obtiene ra\xEDces directamente.","Entrega todas las ra\xEDces reales en un solo desarrollo.","\xDAtil did\xE1cticamente: muestra paso a paso coeficientes, p,q, \u0394, caso.","Maneja ra\xEDces m\xFAltiples y el caso con tres ra\xEDces reales v\xEDa trigonometr\xEDa."],limitaciones:["Solo aplica a polinomios de grado exactamente 3.","No aplica a funciones trascendentes (e\u02E3, sen(x), ln(x), etc.).","La forma cl\xE1sica puede ser inestable con coeficientes muy grandes/peque\xF1os (propio de radicales).","Requiere cuidado con \u0394 muy pr\xF3ximo a cero por precisi\xF3n num\xE9rica."],recomendaciones:["Verificar siempre que el polinomio sea c\xFAbico (grado 3).","Usar el umbral para clasificar \u0394 correctamente cuando hay ra\xEDces m\xFAltiples.","Al presentar resultados, mostrar ra\xEDces con formato razonable (8 decimales) y verificar f(x)\u22480.","Para tres ra\xEDces reales, preferir siempre la forma trigonom\xE9trica de Vi\xE8te."]},ejemploNormal:{id:"cardano-teoria-numerico",titulo:"Cardano: c\xFAbica con una ra\xEDz real",tipo:"numerico",enunciado:"Resolver x\xB3 \u2212 x \u2212 2 = 0 con la f\xF3rmula de Cardano. a=1,b=0,c=\u22121,d=\u22122. Calcular m,p,q,\u0394 y obtener las ra\xEDces reales.",ecuacion:"x\xB3 \u2212 x \u2212 2 = 0",parametros:[{etiqueta:"Coeficientes",valor:"a=1, b=0, c=-1, d=-2"},{etiqueta:"Forma deprimida",valor:"t\xB3 + p\xB7t + q = 0"}],interpretacion:"\u0394 = (q/2)\xB2 + (p/3)\xB3 > 0: corresponde a una ra\xEDz real y dos complejas conjugadas. Aplicando Cardano cl\xE1sico obtenemos la ra\xEDz real x = t + m. Las complejas no se listan en la tabla por ser ra\xEDces no reales buscadas en este contexto did\xE1ctico.",pasos:["Paso 0 \u2014 Coeficientes: a=1, b=0, c=\u22121, d=\u22122. Verificar grado 3: ok.","Paso 1 \u2014 Desplazamiento m = \u2212b/(3a) = 0. Forma deprimida mantiene coeficientes.","Paso 2 \u2014 p = (3a c \u2212 b\xB2)/(3a\xB2) = (3\xB71\xB7(\u22121) \u2212 0)/(3) = \u22123/3 = \u22121. q = (2b\xB3 \u2212 9a b c + 27a\xB2 d)/(27a\xB3) = (0 \u2212 0 + 27\xB71\xB7(\u22122))/(27) = \u221254/27 = \u22122. t\xB3 \u2212 t \u2212 2 = 0.","Paso 3 \u2014 q/2 = \u22121, (q/2)\xB2 = 1. p/3 = \u22121/3, (p/3)\xB3 = \u22121/27. \u0394 = 1 + (\u22121/27) = 26/27 = 0.9629629629629629 > 0.","Paso 4 \u2014 Caso \u0394 > 0 (una ra\xEDz real): A = \u2212q/2 + \u221A\u0394 = \u2212(\u22121) + \u221A(0.9629629629629629) = 1 + 0.9813067629253164 = 1.9813067629253163. B = \u2212q/2 \u2212 \u221A\u0394 = 1 \u2212 0.9813067629253164 = 0.018693237074683622.","Paso 5 \u2014 t = \xB3\u221AA + \xB3\u221AB = \xB3\u221A1.9813067629253163 + \xB3\u221A0.018693237074683622 = 1.2559834226476907 + 0.2653962841568766 = 1.5213797068045674.","Paso 6 \u2014 Deshacer el desplazamiento: x = t + m = 1.5213797068045674 + 0 = 1.5213797068045674."],algoritmo:"Con m=0, p=\u22121, q=\u22122: \u0394=(q/2)\xB2+(p/3)\xB3=(\u22121)\xB2+(\u22121/3)\xB3=0.96296296>0 \u2192 Cardano cl\xE1sico. t = \xB3\u221A(1 + \u221A\u0394) + \xB3\u221A(1 \u2212 \u221A\u0394)=1.5213797068045674.",criterio:"\u0394>0 \u21D2 una ra\xEDz real. Ra\xEDz \xFAnica real encontrada: x\u22481.5213797068045674.",conclusion:"Ra\xEDz real: x \u2248 1.52137971. f(x)=x\xB3\u2212x\u22122 evaluada en esa ra\xEDz es ~0 (residuo num\xE9rico despreciable).",calculo:{funcion:"x^3 - x - 2"}},ejemploCasuistica:{id:"cardano-teoria-casuistica",titulo:"Tres ra\xEDces reales: sensor \u0394 < 0 (Vi\xE8te trigonom\xE9trico)",tipo:"casuistica",enunciado:"El sensor de nivel se calibra con V(\u0394)=\u0394\xB3 \u2212 7\u0394 + 4 = 0 (mismo problema que otros m\xE9todos). Resolver con Cardano: a=1,b=0,c=\u22127,d=4. Obtener las tres ra\xEDces reales con Vi\xE8te trigonom\xE9trico.",ecuacion:"x^3 \u2212 7x + 4 = 0",parametros:[{etiqueta:"Ley",valor:"V(\u0394)=\u0394\xB3 \u2212 7\u0394 + 4 = 0"},{etiqueta:"Coeficientes",valor:"a=1,b=0,c=-7,d=4"}],extraccion:{busqueda:"las correcciones \u0394 que anulan V(\u0394)=\u0394\xB3 \u2212 7\u0394 + 4 (ra\xEDces reales) para calibrar el sensor.",datos:[{simbolo:"a,b,c,d",valor:"1,0,-7,4",queEs:"coeficientes de la c\xFAbica"},{simbolo:"p,q",valor:"-7,4",queEs:"coeficientes forma deprimida t\xB3 + p t + q = 0"},{simbolo:"\u0394",valor:"< 0",queEs:"discriminante \u2192 tres ra\xEDces reales"}],formulacion:"m=0, p=\u22127, q=4. \u0394=(q/2)\xB2+(p/3)\xB3=(2)\xB2+(\u22127/3)\xB3=4 \u2212 343/27=(108\u2212343)/27=\u2212235/27\u2248\u22128.7037037. Al ser \u0394<0 usamos Vi\xE8te trigonom\xE9trico: t_k = 2\xB7\u221A(\u2212p/3)\xB7cos((\u03C6 \u2212 2k\u03C0)/3), \u03C6=arccos((\u2212q/2)/\u221A(\u2212(p/3)\xB3)), k=0,1,2. Desplazamiento m=0 \u21D2 x_k = t_k."},interpretacion:"\u0394<0 implica tres ra\xEDces reales distintas. La forma trigonom\xE9trica evita el casus irreducibilis y entrega directamente las tres ra\xEDces con buena estabilidad num\xE9rica.",pasos:["Paso 0 \u2014 Coeficientes: a=1,b=0,c=\u22127,d=4.","Paso 1 \u2014 m=0. p=(3\xB71\xB7(\u22127)\u22120)/(3)=\u22127. q=(0 \u2212 0 + 27\xB71\xB74)/(27)=4. t\xB3 \u2212 7t + 4 = 0.","Paso 2 \u2014 \u0394=(q/2)\xB2+(p/3)\xB3=(2)\xB2+(\u22127/3)\xB3=4 \u2212 343/27=\u2212235/27=\u22128.703703703703704 < 0.","Paso 3 \u2014 Caso \u0394 < 0 (tres ra\xEDces reales): \u2212p/3 = \u2212(\u22127)/3=7/3=2.3333333333333335, \u221A(\u2212p/3)=\u221A2.3333333333333335=1.5275252316519468, factor 2\xB7\u221A(\u2212p/3)=3.0550504633038936.","Paso 4 \u2014 \u2212(p/3)\xB3 = \u2212(\u2212343/27)=343/27=12.703703703703704, \u221A(\u2212(p/3)\xB3)=3.5637059362410924. \u2212q/2=\u22122. (\u2212q/2)/\u221A(\u2212(p/3)\xB3)=\u22122/3.5637059362410924=\u22120.5612310241546865. \u03C6=arccos(\u22120.5612310241546865)=2.164208272473024 rad.","Paso 5 \u2014 k=0: (\u03C6)/3=0.721402757491008, cos=0.7513101617791627, t\u2080=3.0550504633038936\xB70.7513101617791627=2.2924015852246216.","Paso 6 \u2014 k=1: (\u03C6 \u2212 2\u03C0)/3=(2.164208272473024 \u2212 6.283185307179586)/3=\u22121.3729923449021873, cos(\u22121.3729923449021873)=0.19722627489287316, t\u2081=3.0550504633038936\xB70.19722627489287316=0.6027049307029097.","Paso 7 \u2014 k=2: (\u03C6 \u2212 4\u03C0)/3=(2.164208272473024 \u2212 12.566370614359172)/3=\u22123.4673874472953827, cos(\u22123.4673874472953827)=\u22120.9475364366720358, t\u2082=3.0550504633038936\xB7(\u22120.9475364366720358)=\u22122.895106515927531.","Paso 8 \u2014 x = t + m = t: \u22122.895106515927531, 0.6027049307029097, 2.2924015852246216. Ordenadas de menor a mayor."],algoritmo:"p=\u22127,q=4, \u0394<0. Vi\xE8te: 2\xB7\u221A(7/3)=3.0550504633038936, \u03C6=arccos(\u2212q/2 / \u221A(\u2212(p/3)\xB3))=arccos(\u22122/3.5637059362410924)=2.164208272473024. k=0,1,2 \u2192 tres t reales.",criterio:"\u0394<0 \u21D2 tres ra\xEDces reales distintas. Tres ra\xEDces encontradas.",conclusion:"Ra\xEDces reales: x\u2081 \u2248 \u22122.89510652, x\u2082 \u2248 0.60270493 y x\u2083 \u2248 2.29240159. Las tres verifican: al evaluar f en cada una queda un residuo num\xE9rico despreciable.",calculo:{funcion:"x^3 - 7x + 4"}}},e=[{id:"cardano-ej1-raiz-doble",titulo:"Ra\xEDz doble y ra\xEDz simple (\u0394=0)",tipo:"numerico",enunciado:"Resolver x\xB3 \u2212 3x + 2 = 0 con Cardano. Hallar ra\xEDces reales (doble y simple).",ecuacion:"x\xB3 \u2212 3x + 2 = 0",parametros:[{etiqueta:"Coeficientes",valor:"a=1,b=0,c=-3,d=2"},{etiqueta:"Caso",valor:"\u0394=0 (ra\xEDz m\xFAltiple)"}],interpretacion:"\u0394=0 indica al menos una ra\xEDz doble. Cardano da t\u2081=\u22122\xB7(q/2)^(1/3), t\u2082=t\u2083=(q/2)^(1/3).",pasos:["Paso 0 \u2014 a=1,b=0,c=\u22123,d=2. m=0.","Paso 1 \u2014 p=(3\xB71\xB7(\u22123))/(3)=\u22123. q=(27\xB71\xB72)/(27)=2. t\xB3 \u2212 3t + 2 = 0.","Paso 2 \u2014 \u0394=(q/2)\xB2+(p/3)\xB3: q/2=1, p/3=\u22121 \u21D2 (1)\xB2 + (\u22121)\xB3 = 1 \u2212 1 = 0.","Paso 3 \u2014 \u0394==0: t\u2081 = \u22122\xB7(q/2)^(1/3)=\u22122\xB71=\u22122. t\u2082=t\u2083 = (q/2)^(1/3)=1.","Paso 4 \u2014 x = t+m: x=\u22122, x=1, x=1.","Paso 5 \u2014 Ra\xEDces reales: \u22122, 1 (doble).","Paso 6 \u2014 Verificaci\xF3n: f(\u22122)=\u22128+6+2=0, f(1)=1\u22123+2=0."],algoritmo:"m=0, p=\u22123, q=2, \u0394=0. La deprimida t\xB3\u22123t+2 se factoriza como (t+2)(t\u22121)\xB2: sale t=\u22122 (ra\xEDz simple) y t=1 (ra\xEDz doble). Como m=0, x=t+m deja x=\u22122 y x=1.",criterio:"\u0394==0 \u21D2 hay ra\xEDz m\xFAltiple: una ra\xEDz doble (x=1) y una simple (x=\u22122). Cardano entrega las dos, y el detalle de la tabla dice cu\xE1l de ellas se repite.",conclusion:"Ra\xEDces reales: x \u2248 \u22122 (ra\xEDz simple) y x \u2248 1 (ra\xEDz doble, multiplicidad 2). Verificaci\xF3n: f(\u22122)=0 y f(1)=0, y el polinomio se factoriza como (x+2)(x\u22121)\xB2.",calculo:{funcion:"x^3 - 3x + 2"}},{id:"cardano-ej2-tres-reales-viete",titulo:"Tres ra\xEDces reales distintas (Vi\xE8te)",tipo:"numerico",enunciado:"Resolver x\xB3 \u2212 3x + 1 = 0 con Cardano. Obtener las tres ra\xEDces reales.",ecuacion:"x^3 \u2212 3x + 1 = 0",parametros:[{etiqueta:"Coeficientes",valor:"a=1,b=0,c=-3,d=1"},{etiqueta:"Caso",valor:"\u0394<0 \u2192 tres reales (Vi\xE8te trig.)"}],interpretacion:"\u0394<0: usar forma trigonom\xE9trica de Vi\xE8te para obtener tres ra\xEDces reales.",pasos:["Paso 0 \u2014 a=1,b=0,c=\u22123,d=1. m=0.","Paso 1 \u2014 p=\u22123, q=1. t\xB3 \u2212 3t + 1 = 0.","Paso 2 \u2014 \u0394=(q/2)\xB2+(p/3)\xB3=(0.5)\xB2+(\u22121)^3=0.25\u22121=\u22120.75 < 0.","Paso 3 \u2014 \u2212p/3=1, \u221A(\u2212p/3)=1, 2\xB7\u221A(\u2212p/3)=2. \u2212(p/3)\xB3=1, \u221A(\u2212(p/3)\xB3)=1. (\u2212q/2)/1=(\u22120.5)/1=\u22120.5. \u03C6=arccos(\u22120.5)=2\u03C0/3=2.0943951023931953.","Paso 4 \u2014 k=0: \u03C6/3=0.6981317007977318, cos=0.766044443118978, t\u2080=2\xB70.766044443118978=1.532088886237956.","Paso 5 \u2014 k=1: (\u03C6\u22122\u03C0)/3=(2.0943951023931953\u22126.283185307179586)/3=\u22121.3962634015954636, cos=cos(\u22121.396263)=cos(1.396263)=0.17364817766693041, t\u2081=2\xB70.17364817766693041=0.3472963553338607.","Paso 6 \u2014 k=2: (\u03C6\u22124\u03C0)/3=(2.0943951023931953\u221212.566370614359172)/3=\u22123.490658503988659, cos=cos(\u22123.490659)=cos(3.490659)=cos(200\xB0)=\u22120.9396926207859084, t\u2082=2\xB7(\u22120.9396926207859084)=\u22121.8793852415718169.","Paso 7 \u2014 x = t: \u22121.8793852415718169, 0.3472963553338607, 1.532088886237956. Ordenadas."],algoritmo:"p=\u22123,q=1, \u0394<0. Vi\xE8te con \u03C6=2\u03C0/3 \u2192 tres ra\xEDces reales.",criterio:"\u0394<0 \u21D2 tres ra\xEDces reales distintas: el caso irreducible, que se resuelve con la forma trigonom\xE9trica de Vi\xE8te en lugar de la f\xF3rmula de radicales.",conclusion:"Ra\xEDces reales: x \u2248 \u22121.87938524, x \u2248 0.34729636, x \u2248 1.53208889.",calculo:{funcion:"x^3 - 3x + 1"}},{id:"cardano-ej3-caja-cubic",titulo:"Cubic con ra\xEDces m\xFAltiples (aplicaci\xF3n: volumen de caja)",tipo:"casuistica",enunciado:"Se corta x dm de cada esquina de una plancha cuadrada de 12\xD712 dm y se dobla para formar una caja. Se quiere volumen V=128 dm\xB3. Ecuaci\xF3n: (12\u22122x)\xB2\xB7x = 128 \u21D2 x\xB3 \u2212 12x\xB2 + 36x \u2212 32 = 0. Resolver con Cardano.",ecuacion:"x^3 \u2212 12x\xB2 + 36x \u2212 32 = 0",parametros:[{etiqueta:"Aplicaci\xF3n",valor:"Volumen caja V=128 dm\xB3"},{etiqueta:"Ecuaci\xF3n",valor:"x\xB3 \u2212 12x\xB2 + 36x \u2212 32 = 0"},{etiqueta:"Coeficientes",valor:"a=1,b=-12,c=36,d=-32"}],extraccion:{busqueda:"altura x (dm) de la caja tal que (12\u22122x)\xB2\xB7x = 128.",datos:[{simbolo:"12\xD712",valor:"dm\xB2",queEs:"plancha cuadrada"},{simbolo:"x",valor:"dm",queEs:"corte en cada esquina"},{simbolo:"V",valor:"128 dm\xB3",queEs:"volumen deseado"}],formulacion:"V=(12\u22122x)\xB2 x = 128. Expandimos: (144 \u2212 48x + 4x\xB2)x = 144x \u2212 48x\xB2 + 4x\xB3 = 128 \u21D2 4x\xB3 \u2212 48x\xB2 + 144x \u2212 128 = 0 \u21D2 dividir por 4: x\xB3 \u2212 12x\xB2 + 36x \u2212 32 = 0. Reducci\xF3n: m=\u2212b/(3a)=\u2212(\u221212)/3=4. p=(3a c \u2212 b\xB2)/(3a\xB2)=(3\xB71\xB736 \u2212 144)/3=(108\u2212144)/3=\u221212. q=(2b\xB3 \u2212 9a b c + 27a\xB2 d)/(27a\xB3): con b=\u221212, b\xB3=\u22121728 \u21D2 2b\xB3=\u22123456; \u22129\xB71\xB7(\u221212)\xB736=+3888; 27\xB71\xB7(\u221232)=\u2212864. Numerador \u22123456+3888\u2212864=\u2212432, denominador 27a\xB3=27 \u21D2 q=\u221216. Deprimida: t\xB3 \u2212 12t \u2212 16 = 0. \u0394=(q/2)\xB2+(p/3)\xB3=(\u22128)\xB2+(\u22124)\xB3=64\u221264=0."},interpretacion:"\u0394=0 indica ra\xEDz m\xFAltiple. x = t+m. Soluci\xF3n f\xEDsica: x=2 (ra\xEDz doble) y x=8; x=8 fuera de dominio (12\u22122*8=\u22124), quedando x=2 (doble).",pasos:["Paso 0 \u2014 a=1,b=\u221212,c=36,d=\u221232.","Paso 1 \u2014 m=\u2212b/(3a)=\u2212(\u221212)/3=4.","Paso 2 \u2014 p=(3a c \u2212 b\xB2)/(3a\xB2)=(3\xB71\xB736 \u2212 144)/(3)=(108\u2212144)/3=\u221212. q=(2b\xB3 \u2212 9a b c + 27a\xB2 d)/(27a\xB3)= (2\xB7(\u22121728) \u2212 9\xB71\xB7(\u221212)\xB736 + 27\xB71\xB7(\u221232))/(27)= (\u22123456 + 3888 \u2212 864)/27=(\u2212432)/27=\u221216. t\xB3 \u2212 12t \u2212 16 = 0.","Paso 3 \u2014 \u0394=(q/2)\xB2+(p/3)\xB3=(\u22128)\xB2+(\u22124)^3=64\u221264=0.","Paso 4 \u2014 \u0394==0: t\u2081=\u22122\xB7(q/2)^(1/3)=\u22122\xB7(\u22122)=4. t\u2082=t\u2083=(q/2)^(1/3)=\u22122.","Paso 5 \u2014 x = t+m: t=4\u2192x=8, t=\u22122\u2192x=2, t=\u22122\u2192x=2.","Paso 6 \u2014 Ra\xEDces: 2 (doble), 8. Dominio f\xEDsico x\u2208(0,6) \u21D2 x=2.","Paso 7 \u2014 Verificaci\xF3n V=(12\u22124)\xB2\xB72=8\xB2\xB72=128. OK."],algoritmo:"m=4, p=\u221212, q=\u221216, \u0394=0. La deprimida t\xB3\u221212t\u221216 se factoriza como (t\u22124)(t+2)\xB2: sale t=4 (ra\xEDz simple) y t=\u22122 (ra\xEDz doble). Deshaciendo el desplazamiento x=t+m quedan x=8 y x=2 (doble).",criterio:"\u0394==0 \u21D2 ra\xEDz doble y ra\xEDz simple. Interpretaci\xF3n f\xEDsica requerida.",conclusion:"Ra\xEDces reales: x \u2248 2 (ra\xEDz doble), x \u2248 8. Para caja v\xE1lida, x=2 dm (x=8 fuera de dominio).",calculo:{funcion:"x^3 - 12x^2 + 36x - 32"}},{id:"cardano-ej4-consecutivos",titulo:"N\xFAmeros consecutivos (aplicaci\xF3n)",tipo:"casuistica",enunciado:"Tres n\xFAmeros enteros consecutivos multiplicados entre s\xED dan 24: (x\u22121)x(x+1)=x\xB3 \u2212 x = 24 \u21D2 x\xB3 \u2212 x \u2212 24 = 0. Resolver con Cardano.",ecuacion:"x^3 \u2212 x \u2212 24 = 0",parametros:[{etiqueta:"Problema",valor:"(x\u22121)x(x+1)=24"},{etiqueta:"Ecuaci\xF3n",valor:"x^3 \u2212 x \u2212 24 = 0"},{etiqueta:"Coeficientes",valor:"a=1,b=0,c=-1,d=-24"}],extraccion:{busqueda:"x tal que el producto de tres consecutivos (x\u22121,x,x+1)=24.",datos:[{simbolo:"(x\u22121),x,(x+1)",valor:"enteros consecutivos",queEs:"n\xFAmeros buscados"},{simbolo:"producto",valor:"24",queEs:"producto de los tres n\xFAmeros consecutivos"}],formulacion:"(x\u22121)x(x+1)=x(x\xB2\u22121)=x\xB3\u2212x=24 \u21D2 x\xB3\u2212x\u221224=0. a=1,b=0,c=\u22121,d=\u221224. m=0, p=\u22121, q=\u221224. \u0394=(q/2)\xB2+(p/3)\xB3=(\u221212)\xB2+(\u22121/3)^3=144 \u2212 1/27=143.96296296296296>0."},interpretacion:"\u0394>0 \u21D2 una sola ra\xEDz real: las otras dos son complejas conjugadas y no interesan en este problema. La ra\xEDz real da el n\xFAmero central x=3, de modo que los tres n\xFAmeros consecutivos buscados son 2, 3 y 4.",pasos:["Paso 0 \u2014 Coeficientes: a=1, b=0, c=\u22121, d=\u221224. Verificar grado 3: ok.","Paso 1 \u2014 m=\u2212b/(3a)=0. p=(3a c \u2212 b\xB2)/(3a\xB2)=(\u22123\u22120)/3=\u22121. q=(2b\xB3 \u2212 9a b c + 27a\xB2 d)/(27a\xB3)=(0 \u2212 0 + 27\xB7(\u221224))/27=\u221224. Deprimida: t\xB3 \u2212 t \u2212 24 = 0.","Paso 2 \u2014 \u0394=(q/2)\xB2+(p/3)\xB3=(\u221212)\xB2+(\u22121/3)\xB3=144 \u2212 1/27 = 143.96296296296296 > 0.","Paso 3 \u2014 Caso \u0394 > 0: \u2212q/2 = 12, \u221A\u0394 = 11.998456690881664.","Paso 4 \u2014 A = \u2212q/2 + \u221A\u0394 = 12 + 11.998456690881664 = 23.998456690881664. B = \u2212q/2 \u2212 \u221A\u0394 = 12 \u2212 11.998456690881664 = 0.0015433091183361114.","Paso 5 \u2014 t = \xB3\u221AA + \xB3\u221AB = \xB3\u221A23.998456690881664 + \xB3\u221A0.0015433091183361114 = 2.8844373104863457 + 0.11556268951364888 = 2.9999999999999947, que redondeado es 3 (la ra\xEDz exacta es entera).","Paso 6 \u2014 Deshacer el desplazamiento: x = t + m = 2.9999999999999947 + 0 = 3.","Paso 7 \u2014 Ra\xEDz real: x=3. Los tres n\xFAmeros consecutivos son 2, 3 y 4 (2\xB73\xB74=24)."],algoritmo:"m=0, p=\u22121, q=\u221224, \u0394>0 \u21D2 una ra\xEDz real. Con A=\u2212q/2+\u221A\u0394=23.998456690881664 y B=\u2212q/2\u2212\u221A\u0394=0.0015433091183361114 sale t=\xB3\u221AA+\xB3\u221AB=2.9999999999999947, de donde x=t+m=3.",criterio:"\u0394>0 \u21D2 una \xFAnica ra\xEDz real, que en este caso da un entero: x=3 (los tres n\xFAmeros consecutivos son 2, 3 y 4).",conclusion:"Ra\xEDz real: x \u2248 3.0. Los tres n\xFAmeros consecutivos son 2,3,4 (2\xB73\xB74=24).",calculo:{funcion:"x^3 - x - 24"}}],o=[{id:"cardano-ejercicio-triple",titulo:"Ra\xEDz triple",tipo:"numerico",enunciado:"Resolver (x+1)^3 = 0 con Cardano. Identificar la naturaleza de las ra\xEDces.",ecuacion:"(x+1)^3 = 0",parametros:[{etiqueta:"Forma expandida",valor:"x^3 + 3x^2 + 3x + 1 = 0"},{etiqueta:"Coeficientes",valor:"a=1,b=3,c=3,d=1"}],pista:"Expandir (x+1)^3 = x\xB3+3x\xB2+3x+1. Reducir: m=\u2212b/(3a)=\u22121. Calcular p,q y ver \u0394.",interpretacion:"\u0394=0 y adem\xE1s p=q=0: la deprimida es t\xB3=0, o sea una ra\xEDz triple. Las tres ra\xEDces coinciden en x=\u22121 y el polinomio se factoriza como (x+1)\xB3.",pasos:["Paso 0 \u2014 Expandir: (x+1)^3=x\xB3+3x\xB2+3x+1, a=1,b=3,c=3,d=1.","Paso 1 \u2014 m=\u2212b/(3a)=\u22121.","Paso 2 \u2014 p=(3a c \u2212 b\xB2)/(3a\xB2)=(9 \u2212 9)/(3)=0. q=(2b\xB3 \u2212 9a b c + 27a\xB2 d)/(27a\xB3). b\xB3=27, 2b\xB3=54. \u22129a b c = \u22129\xB71\xB73\xB73 = \u221281. 27a\xB2 d = 27. Numerador: 54 \u2212 81 + 27 = 0. q=0. t\xB3 + 0\xB7t + 0 = t\xB3=0.","Paso 3 \u2014 \u0394=(q/2)\xB2+(p/3)\xB3=0. Con p=0 y q=0 \u21D2 \u0394=0.","Paso 4 \u2014 \u0394==0: t\u2081=\u22122\xB7(q/2)^(1/3)=0. t\u2082=t\u2083=0.","Paso 5 \u2014 x = t+m = \u22121, \u22121, \u22121.","Paso 6 \u2014 Ra\xEDz triple: x=\u22121."],algoritmo:"m=\u22121, p=0, q=0, \u0394=0. Como p=q=0, la deprimida es t\xB3=0 y sale la ra\xEDz triple t=0; deshaciendo el desplazamiento, x=t+m=\u22121.",criterio:"\u0394==0 con p=q=0 \u21D2 ra\xEDz triple: las tres ra\xEDces coinciden en el mismo valor y no hay ra\xEDces complejas.",conclusion:"Ra\xEDz real triple: x \u2248 \u22121 (multiplicidad 3). Es la \xFAnica ra\xEDz real: al evaluar f(\u22121) queda (\u22121)\xB3+3(\u22121)\xB2+3(\u22121)+1=0, por eso el polinomio se anula solo en ese punto.",calculo:{funcion:"x^3 + 3x^2 + 3x + 1"}},{id:"cardano-ejercicio-a-diferente",titulo:"C\xFAbica con coeficiente a!=1",tipo:"numerico",enunciado:"Resolver 2x\xB3 + 3x\xB2 \u2212 11x \u2212 6 = 0 con Cardano.",ecuacion:"2x^3 + 3x^2 \u2212 11x \u2212 6 = 0",parametros:[{etiqueta:"Coeficientes",valor:"a=2,b=3,c=-11,d=-6"},{etiqueta:"Caso",valor:"\u0394<0 \u2192 tres ra\xEDces reales (Vi\xE8te trigonom\xE9trico)"}],pista:"Usar f\xF3rmulas con a=2: m=\u2212b/(3a), p=(3a c \u2212 b\xB2)/(3a\xB2), q=(2b\xB3 \u2212 9a b c + 27a\xB2 d)/(27a\xB3).",interpretacion:"Tres ra\xEDces reales, aunque el coeficiente de x\xB3 no sea 1: el motor lee a=2 del polinomio y aplica la f\xF3rmula con ese valor, no con uno normalizado a 1.",pasos:["Paso 0 \u2014 a=2,b=3,c=\u221211,d=\u22126.","Paso 1 \u2014 m=\u2212b/(3a)=\u22123/6=\u22120.5.","Paso 2 \u2014 3a c = 3\xB72\xB7(\u221211)=\u221266. b\xB2=9. Numerador p: \u221266\u22129=\u221275. 3a\xB2=3\xB74=12. p=\u221275/12=\u221225/4=\u22126.25.","Paso 3 \u2014 b\xB3=27, 2b\xB3=54. \u22129a b c = \u22129\xB72\xB73\xB7(\u221211)= +594. 27a\xB2 d = 27\xB74\xB7(\u22126)=\u2212648. Numerador q: 54 + 594 \u2212 648 = 0. Denom 27a\xB3=27\xB78=216. q=0/216=0. t\xB3 \u2212 6.25t + 0 = t(t\xB2 \u2212 6.25)=0.","Paso 4 \u2014 t\xB3 + p t + q = t\xB3 \u2212 6.25t = 0 \u21D2 t(t\xB2 \u2212 25/4)=0 \u21D2 t=0, t=\xB15/2=\xB12.5.","Paso 5 \u2014 x = t+m = t \u2212 0.5: t=2.5\u21922.0, t=0\u2192\u22120.5, t=\u22122.5\u2192\u22123.0.","Paso 6 \u2014 Ra\xEDces: \u22123, \u22120.5, 2."],algoritmo:"m=\u22120.5, p=\u22126.25, q=0. \u0394=(q/2)\xB2+(p/3)\xB3=0 + (\u22122.0833)\xB3=\u22129.042245370370372 < 0. Tres ra\xEDces reales.",criterio:"Tres ra\xEDces reales. Caso con q=0 simplificado.",conclusion:"Ra\xEDces reales: x \u2248 \u22123, x \u2248 \u22120.5 y x \u2248 2. Verificaci\xF3n: el factorizado es 2(x+3)(x+0.5)(x\u22122), as\xED que cada uno de los tres valores anula f(x).",calculo:{funcion:"2x^3 + 3x^2 - 11x - 6"}},{id:"cardano-ejercicio-dron",titulo:"Dron: tiempo de encuentro",tipo:"casuistica",enunciado:"La altura de un dron sigue h(t)=t\xB3 \u2212 6t\xB2 + 11t \u2212 6 metros. \xBFEn qu\xE9 instantes h(t)=0? Resolver con Cardano.",ecuacion:"t^3 \u2212 6t\xB2 + 11t \u2212 6 = 0",parametros:[{etiqueta:"Funci\xF3n",valor:"h(t)=t\xB3 \u2212 6t\xB2 + 11t \u2212 6"},{etiqueta:"Pregunta",valor:"h(t)=0"},{etiqueta:"Coeficientes",valor:"a=1,b=-6,c=11,d=-6"}],pista:"m=\u2212b/(3a)=2. Calcular p,q. \u0394 puede ser negativo o positivo seg\xFAn valores.",extraccion:{busqueda:"instantes t cuando la altura del dron es cero.",datos:[{simbolo:"h(t)",valor:"m",queEs:"altura en funci\xF3n del tiempo"},{simbolo:"t",valor:"s",queEs:"tiempo transcurrido desde el despegue"}],formulacion:"h(t)=t\xB3 \u2212 6t\xB2 + 11t \u2212 6 = 0. m=\u2212(\u22126)/3=2. p=(3\xB71\xB711 \u2212 36)/3=(33\u221236)/3=\u22121. q=(2b\xB3 \u2212 9a b c + 27a\xB2 d)/(27a\xB3): con b=\u22126, b\xB3=\u2212216 \u21D2 2b\xB3=\u2212432; \u22129\xB71\xB7(\u22126)\xB711=+594; 27\xB71\xB7(\u22126)=\u2212162. Numerador \u2212432+594\u2212162=0 \u21D2 q=0. Deprimida: t\xB3 \u2212 t = t(t\xB2\u22121)=0 \u21D2 t=0,\xB11. Deshacer: x=t+m = 1,2,3. Ordenados 1,2,3."},interpretacion:"Tres ra\xEDces reales: 1,2,3 segundos. El dron pasa por altura 0 en esos instantes.",pasos:["Paso 0 \u2014 a=1,b=\u22126,c=11,d=\u22126.","Paso 1 \u2014 m=2.","Paso 2 \u2014 p=(3\xB711 \u2212 36)/(3)=\u22121. q=(2\xB7(\u2212216) \u2212 9\xB7(\u22126)\xB711 + 27\xB7(\u22126))/(27)= (\u2212432 + 594 \u2212 162)/27=0. t\xB3 \u2212 t = 0.","Paso 3 \u2014 t(t\u22121)(t+1)=0 \u21D2 t=\u22121,0,1.","Paso 4 \u2014 x = t+m = 1,2,3.","Paso 5 \u2014 Ra\xEDces: 1,2,3 s."],algoritmo:"m=2,p=\u22121,q=0, \u0394=(0)\xB2 + (\u22121/3)^3 = \u22121/27 < 0. Tres ra\xEDces reales 1,2,3.",criterio:"Tres ra\xEDces reales (\u0394<0) con resultado entero.",conclusion:"Ra\xEDces reales: x \u2248 1, x \u2248 2, x \u2248 3 segundos. h(1)=h(2)=h(3)=0.",calculo:{funcion:"x^3 - 6x^2 + 11x - 6"}}];export{a,e as b,o as c};
